CREATE TRIGGER scheduling_appointment_guard_0 BEFORE INSERT ON appointments
    WHEN NEW.status != 'CANCELLED' 
    BEGIN
      SELECT RAISE(ABORT,'invalid_practitioner') WHERE NOT EXISTS(SELECT 1 FROM practitioners WHERE id=NEW.practitionerId);
      SELECT RAISE(ABORT,'slot_taken') WHERE EXISTS(SELECT 1 FROM appointments a WHERE a.id!=NEW.id AND a.date=NEW.date AND a.status!='CANCELLED' AND ((CAST(substr(a.startTime,1,2) AS INTEGER)*60+CAST(substr(a.startTime,4,2) AS INTEGER))-a.bufferBefore) < ((CAST(substr(NEW.startTime,1,2) AS INTEGER)*60+CAST(substr(NEW.startTime,4,2) AS INTEGER))+COALESCE(NEW.durationMinutes, CASE NEW.service WHEN 'reeducation-posturale' THEN 50 WHEN 'reeducation-post-partum' THEN 45 WHEN 'massage-therapeutique' THEN 45 WHEN 'drainage-lymphatique' THEN 50 WHEN 'electrotherapie' THEN 30 WHEN 'ultrasons' THEN 20 WHEN 'cavitation' THEN 45 WHEN 'radiofrequence' THEN 60 WHEN 'laser-lipo' THEN 30 WHEN 'pressotherapie' THEN 45 WHEN 'cryolipolyse' THEN 60 WHEN 'massage-amincissant' THEN 45 WHEN 'bilan-minceur' THEN 60 ELSE 30 END)+NEW.bufferAfter) AND ((CAST(substr(NEW.startTime,1,2) AS INTEGER)*60+CAST(substr(NEW.startTime,4,2) AS INTEGER))-NEW.bufferBefore) < ((CAST(substr(a.startTime,1,2) AS INTEGER)*60+CAST(substr(a.startTime,4,2) AS INTEGER))+COALESCE(a.durationMinutes, CASE a.service WHEN 'reeducation-posturale' THEN 50 WHEN 'reeducation-post-partum' THEN 45 WHEN 'massage-therapeutique' THEN 45 WHEN 'drainage-lymphatique' THEN 50 WHEN 'electrotherapie' THEN 30 WHEN 'ultrasons' THEN 20 WHEN 'cavitation' THEN 45 WHEN 'radiofrequence' THEN 60 WHEN 'laser-lipo' THEN 30 WHEN 'pressotherapie' THEN 45 WHEN 'cryolipolyse' THEN 60 WHEN 'massage-amincissant' THEN 45 WHEN 'bilan-minceur' THEN 60 ELSE 30 END)+a.bufferAfter) AND (a.practitionerId=NEW.practitionerId OR (a.patientId IS NOT NULL AND a.patientId=NEW.patientId) OR EXISTS(SELECT 1 FROM json_each(a.resourceIds) r JOIN json_each(NEW.resourceIds) n ON r.value=n.value)));
      SELECT RAISE(ABORT,'slot_blocked') WHERE EXISTS(SELECT 1 FROM blocked_slots b WHERE b.date=NEW.date AND b.practitionerId IN('*',NEW.practitionerId) AND (CAST(substr(b.time,1,2) AS INTEGER)*60+CAST(substr(b.time,4,2) AS INTEGER)) < ((CAST(substr(NEW.startTime,1,2) AS INTEGER)*60+CAST(substr(NEW.startTime,4,2) AS INTEGER))+COALESCE(NEW.durationMinutes, CASE NEW.service WHEN 'reeducation-posturale' THEN 50 WHEN 'reeducation-post-partum' THEN 45 WHEN 'massage-therapeutique' THEN 45 WHEN 'drainage-lymphatique' THEN 50 WHEN 'electrotherapie' THEN 30 WHEN 'ultrasons' THEN 20 WHEN 'cavitation' THEN 45 WHEN 'radiofrequence' THEN 60 WHEN 'laser-lipo' THEN 30 WHEN 'pressotherapie' THEN 45 WHEN 'cryolipolyse' THEN 60 WHEN 'massage-amincissant' THEN 45 WHEN 'bilan-minceur' THEN 60 ELSE 30 END)+NEW.bufferAfter) AND ((CAST(substr(NEW.startTime,1,2) AS INTEGER)*60+CAST(substr(NEW.startTime,4,2) AS INTEGER))-NEW.bufferBefore) < (CAST(substr(b.time,1,2) AS INTEGER)*60+CAST(substr(b.time,4,2) AS INTEGER))+30);
    END

CREATE TRIGGER scheduling_appointment_guard_1 BEFORE UPDATE OF date,startTime,service,status,practitionerId,durationMinutes,bufferBefore,bufferAfter,resourceIds,patientId ON appointments
